// RFC 2104 HMAC built on SHA-256 (64-byte block size). Pure JS.

import { sha256 } from './sha256.mjs';

const BLOCK_SIZE = 64;

/**
 * Compute HMAC-SHA256 of `message` under `key`.
 * @param {Uint8Array} key
 * @param {Uint8Array} message
 * @returns {Uint8Array} 32-byte MAC
 */
export function hmacSha256(key, message) {
  if (!(key instanceof Uint8Array)) {
    throw new TypeError('hmacSha256: key must be a Uint8Array');
  }
  if (!(message instanceof Uint8Array)) {
    throw new TypeError('hmacSha256: message must be a Uint8Array');
  }

  // Keys longer than the block size are hashed first.
  let blockKey = key;
  if (key.length > BLOCK_SIZE) {
    blockKey = sha256(key);
  }
  if (blockKey.length < BLOCK_SIZE) {
    const padded = new Uint8Array(BLOCK_SIZE);
    padded.set(blockKey);
    blockKey = padded;
  }

  const ipad = new Uint8Array(BLOCK_SIZE);
  const opad = new Uint8Array(BLOCK_SIZE);
  for (let i = 0; i < BLOCK_SIZE; i++) {
    ipad[i] = blockKey[i] ^ 0x36;
    opad[i] = blockKey[i] ^ 0x5c;
  }

  const inner = new Uint8Array(BLOCK_SIZE + message.length);
  inner.set(ipad);
  inner.set(message, BLOCK_SIZE);
  const innerHash = sha256(inner);

  const outer = new Uint8Array(BLOCK_SIZE + innerHash.length);
  outer.set(opad);
  outer.set(innerHash, BLOCK_SIZE);
  return sha256(outer);
}

