// Minimal JSON serializer that exactly mimics Python's
// json.dumps(obj, separators=(',', ':'), ensure_ascii=True).
// Pure JS, no dependencies.

const SHORT_ESCAPES = {
  0x08: '\\b',
  0x09: '\\t',
  0x0a: '\\n',
  0x0c: '\\f',
  0x0d: '\\r',
  0x22: '\\"',
  0x5c: '\\\\',
};

function hex4(n) {
  return n.toString(16).padStart(4, '0');
}

// Escape a string the way Python json does with ensure_ascii=True:
// \" \\ \b \f \n \r \t, any char outside 0x20..0x7E as \u00XX / \uXXXX
// (lowercase hex), astral chars as UTF-16 surrogate pairs.
function dumpString(str) {
  let out = '"';
  for (let i = 0; i < str.length; i++) {
    const code = str.charCodeAt(i);
    if (code >= 0x20 && code <= 0x7e && code !== 0x22 && code !== 0x5c) {
      out += str[i];
    } else if (SHORT_ESCAPES[code] !== undefined) {
      out += SHORT_ESCAPES[code];
    } else {
      out += '\\u' + hex4(code);
    }
  }
  return out + '"';
}

// Render a number the way Python json does. Integers print without a
// decimal point; non-integer finite floats fall back to JS shortest
// round-trip formatting (matching Python repr for typical values).
function dumpNumber(num) {
  if (Number.isInteger(num)) {
    // Avoid exponential notation for large safe integers.
    return String(num);
  }
  if (Number.isNaN(num)) return 'NaN';
  if (num === Infinity) return 'Infinity';
  if (num === -Infinity) return '-Infinity';
  let s = String(num);
  // JS uses e.g. "1e+21"; Python uses "1e+21" too, but for exponents
  // Python keeps "e-07"-style two digits only in repr of very small
  // numbers — typical JWT payloads never hit these paths.
  return s;
}

function dumpValue(value) {
  if (value === null) return 'null';
  if (value === true) return 'true';
  if (value === false) return 'false';

  const t = typeof value;
  if (t === 'string') return dumpString(value);
  if (t === 'number') return dumpNumber(value);

  if (Array.isArray(value)) {
    let out = '[';
    for (let i = 0; i < value.length; i++) {
      if (i > 0) out += ',';
      out += dumpValue(value[i]);
    }
    return out + ']';
  }

  if (t === 'object') {
    let out = '{';
    let first = true;
    for (const key of Object.keys(value)) {
      const v = value[key];
      if (v === undefined || typeof v === 'function') continue;
      if (!first) out += ',';
      first = false;
      out += dumpString(key) + ':' + dumpValue(v);
    }
    return out + '}';
  }

  throw new TypeError('Object of type ' + t + ' is not JSON serializable');
}

/**
 * Serialize like Python json.dumps(obj, separators=(',', ':'), ensure_ascii=True).
 * @param {*} obj
 * @returns {string}
 */
export function pyJsonDumps(obj) {
  return dumpValue(obj);
}

