import { sha256 } from '/output/lib/sha256.mjs';
import { hmacSha256 } from '/output/lib/hmac.mjs';

const enc = new TextEncoder();
const hex = (u8) => [...u8].map(b => b.toString(16).padStart(2, '0')).join('');

let pass = 0, fail = 0;
function check(name, actual, expected) {
  const ok = actual === expected;
  console.log(`${ok ? 'PASS' : 'FAIL'} ${name}`);
  console.log(`  got:      ${actual}`);
  if (!ok) console.log(`  expected: ${expected}`);
  ok ? pass++ : fail++;
}

// --- SHA-256 vectors ---
check("sha256('abc')",
  hex(sha256(enc.encode('abc'))),
  'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad');

check("sha256('')",
  hex(sha256(new Uint8Array(0))),
  'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855');

check("sha256(1_000_000 x 'a')",
  hex(sha256(enc.encode('a'.repeat(1_000_000)))),
  'cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0');

// 56-byte input: exercises the padding boundary (two-block message)
check("sha256(56-byte input)",
  hex(sha256(enc.encode('abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq'))),
  '248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1');

// --- HMAC-SHA256 vectors ---
check("HMAC(key='key', fox)",
  hex(hmacSha256(enc.encode('key'), enc.encode('The quick brown fox jumps over the lazy dog'))),
  'f7bc83f430538424b13298e6aa6fb143ef4d59a14946175997479dbc2d1a3cd8');

// RFC 4231 Test Case 2
check("HMAC(key='Jefe', msg)",
  hex(hmacSha256(enc.encode('Jefe'), enc.encode('what do ya want for nothing?'))),
  '5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843');

// RFC 4231 Test Case 1 (key = 20 x 0x0b)
check("HMAC RFC4231 TC1",
  hex(hmacSha256(new Uint8Array(20).fill(0x0b), enc.encode('Hi There'))),
  'b0344c61d8db38535ca8afceaf0bf12b881dc200c9833da726e9376c2e32cff7');

// Long key: 100 x 'a' — independent RFC 2104 re-implementation inline
const longKey = enc.encode('a'.repeat(100));
const msg = enc.encode('some message to authenticate');
const reduced = sha256(longKey);               // key > block size: K' = H(K)
const k0 = new Uint8Array(64); k0.set(reduced);
const ipad = k0.map(b => b ^ 0x36);
const opad = k0.map(b => b ^ 0x5c);
const inner = sha256(new Uint8Array([...ipad, ...msg]));
const independent = hex(sha256(new Uint8Array([...opad, ...inner])));
check("HMAC long key (100 x 'a') internal consistency",
  hex(hmacSha256(longKey, msg)),
  independent);
console.log(`  independent RFC-2104 value: ${independent}`);

// HMAC with empty key and empty message (sanity)
check("HMAC empty key/msg",
  hex(hmacSha256(new Uint8Array(0), new Uint8Array(0))),
  'b613679a0814d9ec772f95d778c35fc5ff1697c493715653c6c712144292c5ad');

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);

