cat > /tmp/verify_base64_json.mjs <<'EOF'
import { base64UrlEncode, base64UrlDecode } from '/output/lib/base64url.mjs';
import { pyJsonDumps } from '/output/lib/jsonutil.mjs';

let pass = 0, fail = 0;
const check = (name, got, want) => {
  const ok = got === want;
  if (ok) pass++; else { fail++; console.log(`FAIL ${name}\n  got:  ${got}\n  want: ${want}`); }
};

// --- base64url round-trips ---
const te = new TextEncoder();
const samples = ['', 'f', 'fo', 'foo', 'foob', 'fooba', 'foobar', 'Hello, 世界! \x00\xff'];
for (const s of samples) {
  const bytes = te.encode(s);
  const enc = base64UrlEncode(bytes);
  const dec = base64UrlDecode(enc);
  check('roundtrip ' + JSON.stringify(s), Buffer.from(dec).equals(Buffer.from(bytes)) ? 'ok' : 'mismatch', 'ok');
  // cross-check against node's Buffer base64url
  check('vs Buffer ' + JSON.stringify(s), enc, Buffer.from(bytes).toString('base64url'));
}
// 256-byte exhaustive round-trip
const all = new Uint8Array(256); for (let i = 0; i < 256; i++) all[i] = i;
check('all-bytes vs Buffer', base64UrlEncode(all), Buffer.from(all).toString('base64url'));
// decode accepts padded and standard-alphabet input
check('padded decode', Buffer.from(base64UrlDecode('aGVsbG8=')).toString(), 'hello');
check('std-alphabet decode', base64UrlEncode(base64UrlDecode('+/8=')), '-_8');
check('empty decode', base64UrlDecode('').length, 0);

// --- pyJsonDumps ---
check('spec example', pyJsonDumps({ sub: '主题', data: 'x"y\nz' }), '{"sub":"\\u4e3b\\u9898","data":"x\\"y\\\\\\nz"}');
check('empty obj', pyJsonDumps({}), '{}');
check('empty arr', pyJsonDumps([]), '[]');
check('nested', pyJsonDumps({ a: [1, true, false, null, { b: 'c' }] }), '{"a":[1,true,false,null,{"b":"c"}]}');
check('escapes', pyJsonDumps('"\b\f\n\r\t\\'), '"\\"\\b\\f\\n\\r\\t\\\\"');
check('ctrl chars', pyJsonDumps(''), '"\\u0000\\u001f"');
check('del char', pyJsonDumps(''), '"\\u007f"');
check('tilde unescaped', pyJsonDumps('~'), '"~"');
check('astral', pyJsonDumps('😀'), '"\\ud83d\\ude00"');
check('bmp accent', pyJsonDumps('é'), '"\\u00e9"');
check('int', pyJsonDumps(42), '42');
check('neg int', pyJsonDumps(-7), '-7');
check('key order', pyJsonDumps({ z: 1, a: 2, m: 3 }), '{"z":1,"a":2,"m":3}');
check('string key escaping', pyJsonDumps({ 'k\n': 1 }), '{"k\\n":1}');

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
EOF
