// argparse.mjs — minimal emulation of:
//   parser = argparse.ArgumentParser()
//   parser.add_argument('--subject', type=str, required=True)
//   parser.add_argument('--user_data', type=str, required=True)
// matching CPython argparse's exact messages, streams, and exit codes.

const OPTION_DEFS = [
  { name: '--subject', dest: 'subject', metavar: 'SUBJECT' },
  { name: '--user_data', dest: 'user_data', metavar: 'USER_DATA' },
];

function usageLine(prog) {
  return `usage: ${prog} [-h] --subject SUBJECT --user_data USER_DATA`;
}

function helpText(prog) {
  return (
    usageLine(prog) +
    '\n\noptions:\n' +
    '  -h, --help            show this help message and exit\n' +
    '  --subject SUBJECT\n' +
    '  --user_data USER_DATA\n'
  );
}

function error(prog, message) {
  process.stderr.write(usageLine(prog) + '\n');
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

// argparse treats a token as an option string if it starts with '-' and is
// not a negative number (no defined options look like negative numbers).
function looksLikeOption(token) {
  return token.length > 1 && token[0] === '-' && !/^-\d/.test(token);
}

export function parseArgs(argv, prog) {
  const values = {};
  const extras = [];

  let i = 0;
  while (i < argv.length) {
    let token = argv[i];
    let inlineValue = null;

    // Split --opt=value form.
    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      if (eq !== -1) {
        inlineValue = token.slice(eq + 1);
        token = token.slice(0, eq);
      }
    }

    if (token === '-h' || token === '--help') {
      process.stdout.write(helpText(prog));
      process.exit(0);
    }

    // Exact match, else unambiguous prefix match (argparse allow_abbrev).
    let def = OPTION_DEFS.find((d) => d.name === token);
    if (!def && token.startsWith('--')) {
      const matches = OPTION_DEFS.filter((d) => d.name.startsWith(token));
      if (matches.length === 1) def = matches[0];
    }

    if (!def) {
      extras.push(inlineValue !== null ? `${token}=${inlineValue}` : token);
      i += 1;
      continue;
    }

    if (inlineValue !== null) {
      values[def.dest] = inlineValue;
      i += 1;
      continue;
    }

    const next = argv[i + 1];
    if (next === undefined || looksLikeOption(next)) {
      error(prog, `argument ${def.name}: expected one argument`);
    }
    values[def.dest] = next;
    i += 2;
  }

  // Required-argument check happens before the unrecognized-argument check
  // (parse_known_args validates required; parse_args reports extras after).
  const missing = OPTION_DEFS.filter((d) => !(d.dest in values)).map((d) => d.name);
  if (missing.length > 0) {
    error(prog, `the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length > 0) {
    error(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return { subject: values.subject, user_data: values.user_data };
}

