// Minimal JWT HS256 implementation replicating python-jose's behavior:
// - encode: header {"alg":"HS256","typ":"JWT"}, payload serialized with
//   Python-style compact json (ensure_ascii), HMAC-SHA256 signature.
// - decode: verifies signature, algorithm whitelist, and the `verify_sub`
//   option (subject claim must be present).

import { hmacSha256 } from './hmac.mjs';
import { base64UrlEncode, base64UrlDecode } from './base64url.mjs';
import { pyJsonDumps } from './jsonutil.mjs';

const encoder = new TextEncoder();
const decoder = new TextDecoder();

function utf8(str) {
  return encoder.encode(str);
}

function timingSafeEqualStr(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

export function encode(payload, secret) {
  const header = { alg: 'HS256', typ: 'JWT' };
  const signingInput =
    base64UrlEncode(utf8(pyJsonDumps(header))) +
    '.' +
    base64UrlEncode(utf8(pyJsonDumps(payload)));
  const signature = hmacSha256(utf8(secret), utf8(signingInput));
  return signingInput + '.' + base64UrlEncode(signature);
}

export function decode(token, secret, { algorithms = null, options = {} } = {}) {
  const parts = token.split('.');
  if (parts.length !== 3) {
    throw new Error('Not enough segments');
  }
  const [encodedHeader, encodedPayload, encodedSignature] = parts;

  const header = JSON.parse(decoder.decode(base64UrlDecode(encodedHeader)));

  if (algorithms !== null) {
    if (!header.alg || !algorithms.includes(header.alg)) {
      throw new Error('The specified alg value is not allowed');
    }
  }

  const signingInput = encodedHeader + '.' + encodedPayload;
  const expected = base64UrlEncode(hmacSha256(utf8(secret), utf8(signingInput)));
  if (!timingSafeEqualStr(expected, encodedSignature)) {
    throw new Error('Signature verification failed.');
  }

  const claims = JSON.parse(decoder.decode(base64UrlDecode(encodedPayload)));

  if (options.verify_sub && !('sub' in claims)) {
    throw new Error('Missing sub claim');
  }

  return claims;
}

