// Node.js (ESM) port of test10.py:
//   python test10.py --subject <str> --user_data <str>
// Encodes a JWT (HS256, secret "key") with {sub, data} claims, prints the
// token, then decodes it with verify_sub and prints the claims as a Python
// dict repr.

import { basename } from 'node:path';
import { fileURLToPath } from 'node:url';

import { parseArgs } from './lib/argparse.mjs';
import { encode, decode } from './lib/jwt.mjs';
import { pyRepr } from './lib/pyrepr.mjs';

const prog = basename(fileURLToPath(import.meta.url));
const args = parseArgs(process.argv.slice(2), prog);

// 创建带subject的token
const secret = 'key';
const payload = {
  sub: args.subject,
  data: args.user_data,
};
const token = encode(payload, secret);
console.log(token);

// 解码时验证subject（通过options参数）
const decoded = decode(token, secret, {
  options: { verify_sub: true },
  algorithms: ['HS256'],
});
console.log(pyRepr(decoded));

